#include <iostream>
using namespace std;

const int MAXN = 100005;
int parent[MAXN];
int rankArr[MAXN];  // 树的高度，用于优化合并

// 查找元素x的根节点（路径压缩）
int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);  // 路径压缩
    }
    return parent[x];
}

// 合并两个元素所在的集合（按秩合并）
void unionSets(int a, int b) {
    int rootA = find(a);
    int rootB = find(b);

    if (rootA == rootB) return;  // 已在同一集合

    // 按秩合并：将矮树合并到高树下
    if (rankArr[rootA] < rankArr[rootB]) {
        parent[rootA] = rootB;
    } else if (rankArr[rootA] > rankArr[rootB]) {
        parent[rootB] = rootA;
    } else {
        parent[rootB] = rootA;
        rankArr[rootA]++;
    }
}

int main() {
    int N, M;
    cin >> N >> M;

    // 初始化：每个元素自成一个集合
    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        rankArr[i] = 0;
    }

    // 处理M个操作
    for (int i = 0; i < M; i++) {
        char op;
        int a, b;
        cin >> op >> a >> b;

        if (op == 'M') {
            unionSets(a, b);  // 合并
        } else if (op == 'Q') {
            // 查询
            if (find(a) == find(b)) {
                cout << "Yes" << endl;
            } else {
                cout << "No" << endl;
            }
        }
    }

    return 0;
}
